        readArb_grantId <= 2'b00;
      end
      if(io_dBus_ar_valid) begin
        readArb_grantId <= 2'b01;
      end
      if(io_udBus_ar_valid) begin
        readArb_grantId <= 2'b10;
      end
    end
  end


endmodule

