    if(ICachePlugin_refetchValid) begin
      IF1_arbitration_haltItself = 1'b1;
    end
  end

  always @(*) begin
    IF1_arbitration_haltByOther = 1'b0;
    if(WaitHandlerPlugin_inLowPowerMode) begin
      IF1_arbitration_haltByOther = 1'b1;
    end
  end

  always @(*) begin
    IF1_arbitration_removeIt = 1'b0;
    if(IF1_arbitration_isFlushed) begin
      IF1_arbitration_removeIt = 1'b1;
    end
  end

  always @(*) begin
    IF1_arbitration_flushIt = 1'b0;
    if(IF1_ProgramCounterPlugin_jumpPipe_valid) begin
      IF1_arbitration_flushIt = 1'b1;
    end
  end

  assign IF1_arbitration_flushNext = 1'b0;
  assign IF1_arbitration_notStuck = (! IF1_arbitration_isStuck);
  always @(*) begin
    IF2_arbitration_haltItself = 1'b0;
    if(IF2_FetchBufferPlugin_isStall) begin
      IF2_arbitration_haltItself = 1'b1;
    end
    case(IF2_ICachePlugin_cacheRefillFSM_stateReg)
      IF2_ICachePlugin_cacheRefillFSM_enumDef_waitAXI : begin
        IF2_arbitration_haltItself = 1'b1;
      end
      IF2_ICachePlugin_cacheRefillFSM_enumDef_readMem : begin
        IF2_arbitration_haltItself = 1'b1;
      end
      IF2_ICachePlugin_cacheRefillFSM_enumDef_commit : begin
        IF2_arbitration_haltItself = 1'b1;
      end
      IF2_ICachePlugin_cacheRefillFSM_enumDef_finish : begin
      end
      default : begin
        if(when_ICachePlugin_l160) begin
          IF2_arbitration_haltItself = 1'b1;
        end
      end
    endcase
