      if(when_Divider_l108) begin
        remainder <= 32'h0;
        numerator <= io_cmd_payload_numerator;
      end
    end else begin
      remainder <= remainderShifted[31:0];
      numerator <= _zz_numerator[31:0];
      if(when_Divider_l127) begin
        remainder <= remainderMinusDenominator[31:0];
      end
    end
  end


