module Comparator (
  input      [31:0]   io_src1,
  input      [31:0]   io_src2,
  input      [3:0]    io_op,
  output              io_result
);
  localparam CompareOpType_EQ = 4'd0;
  localparam CompareOpType_NE = 4'd1;
  localparam CompareOpType_EQZ = 4'd2;
  localparam CompareOpType_NEZ = 4'd3;
  localparam CompareOpType_GE = 4'd4;
  localparam CompareOpType_LT = 4'd5;
  localparam CompareOpType_LE = 4'd6;
  localparam CompareOpType_GT = 4'd7;
  localparam CompareOpType_GEU = 4'd8;
  localparam CompareOpType_LTU = 4'd9;
  localparam CompareOpType_LEU = 4'd10;
  localparam CompareOpType_GTU = 4'd11;
  localparam CompareOpType_GEZ = 4'd12;
  localparam CompareOpType_LTZ = 4'd13;
  localparam CompareOpType_LEZ = 4'd14;
  localparam CompareOpType_GTZ = 4'd15;

  wire       [31:0]   _zz_lt;
  wire       [31:0]   _zz_lt_1;
  wire                eq;
  wire                lt;
  wire                le;
  wire                gt;
  wire                ge;
  wire                ltu;
  wire                leu;
  wire                gtu;
  wire                geu;
  wire                ltz;
  wire                eqz;
  wire                lez;
  wire                gtz;
  wire                gez;
  wire                resultList_1_1;
  wire                resultList_3_1;
  wire                resultList_12_1;
  wire                resultList_13_1;
  reg                 _zz_io_result;
  `ifndef SYNTHESIS
  reg [23:0] io_op_string;
  `endif


  assign _zz_lt = io_src1;
  assign _zz_lt_1 = io_src2;
  `ifndef SYNTHESIS
  always @(*) begin
    case(io_op)
      CompareOpType_EQ : io_op_string = "EQ ";
      CompareOpType_NE : io_op_string = "NE ";
      CompareOpType_EQZ : io_op_string = "EQZ";
      CompareOpType_NEZ : io_op_string = "NEZ";
      CompareOpType_GE : io_op_string = "GE ";
      CompareOpType_LT : io_op_string = "LT ";
      CompareOpType_LE : io_op_string = "LE ";
      CompareOpType_GT : io_op_string = "GT ";
      CompareOpType_GEU : io_op_string = "GEU";
      CompareOpType_LTU : io_op_string = "LTU";
      CompareOpType_LEU : io_op_string = "LEU";
      CompareOpType_GTU : io_op_string = "GTU";
      CompareOpType_GEZ : io_op_string = "GEZ";
      CompareOpType_LTZ : io_op_string = "LTZ";
      CompareOpType_LEZ : io_op_string = "LEZ";
      CompareOpType_GTZ : io_op_string = "GTZ";
      default : io_op_string = "???";
    endcase
  end
  `endif

  assign eq = (io_src1 == io_src2);
  assign lt = ($signed(_zz_lt) < $signed(_zz_lt_1));
  assign le = (lt || eq);
  assign gt = (! le);
  assign ge = (! lt);
  assign ltu = (io_src1 < io_src2);
  assign leu = (ltu || eq);
  assign gtu = (! leu);
  assign geu = (! ltu);
  assign ltz = io_src1[31];
  assign eqz = (! (|io_src1));
  assign lez = (ltz || eqz);
  assign gtz = (! lez);
  assign gez = (! ltz);
  assign resultList_1_1 = (! eq);
  assign resultList_3_1 = (! eqz);
  assign resultList_12_1 = (! ltz);
  assign resultList_13_1 = (! lez);
  always @(*) begin
    case(io_op)
      CompareOpType_EQ : begin
        _zz_io_result = eq;
      end
      CompareOpType_NE : begin
        _zz_io_result = resultList_1_1;
      end
      CompareOpType_EQZ : begin
        _zz_io_result = eqz;
      end
      CompareOpType_NEZ : begin
        _zz_io_result = resultList_3_1;
      end
      CompareOpType_GE : begin
        _zz_io_result = ge;
      end
      CompareOpType_LT : begin
        _zz_io_result = lt;
      end
      CompareOpType_LE : begin
        _zz_io_result = le;
      end
      CompareOpType_GT : begin
        _zz_io_result = gt;
      end
      CompareOpType_GEU : begin
        _zz_io_result = geu;
      end
      CompareOpType_LTU : begin
        _zz_io_result = ltu;
      end
      CompareOpType_LEU : begin
        _zz_io_result = leu;
      end
      CompareOpType_GTU : begin
        _zz_io_result = gtu;
      end
      CompareOpType_GEZ : begin
        _zz_io_result = resultList_12_1;
      end
      CompareOpType_GTZ : begin
        _zz_io_result = resultList_13_1;
      end
      CompareOpType_LEZ : begin
        _zz_io_result = lez;
      end
      default : begin
        _zz_io_result = ltz;
      end
    endcase
  end

  assign io_result = _zz_io_result;

endmodule

module BRU (
  input               io_predictJump,
  input      [31:0]   io_predictAddr,
  input               io_isBranch,
  input               io_isJump,
  input               io_isJR,
  input      [31:0]   io_pc,
  input      [31:0]   io_rj,
  input      [31:0]   io_inst,
  input               io_condition,
  output reg          io_mispredict,
  output reg [31:0]   io_actualTarget
);

  wire       [31:0]   _zz_branchOffset;
  wire       [17:0]   _zz_branchOffset_1;
  wire       [15:0]   _zz_branchOffset_2;
  wire       [31:0]   _zz_jumpTarget;
  wire       [27:0]   _zz_jumpTarget_1;
  wire       [25:0]   _zz_jumpTarget_2;
  wire       [9:0]    _zz_jumpTarget_3;
  wire       [15:0]   _zz_jumpTarget_4;
  wire       [31:0]   _zz_linkTarget;
  wire       [17:0]   _zz_linkTarget_1;
  wire       [31:0]   nextPC;
  wire       [31:0]   branchOffset;
  wire       [31:0]   jumpTarget;
  wire       [31:0]   linkTarget;
  wire                when_BRU_l56;

  assign _zz_branchOffset_1 = {_zz_branchOffset_2,2'b00};
  assign _zz_branchOffset = {{14{_zz_branchOffset_1[17]}}, _zz_branchOffset_1};
  assign _zz_branchOffset_2 = io_inst[25 : 10];
  assign _zz_jumpTarget_1 = {_zz_jumpTarget_2,2'b00};
  assign _zz_jumpTarget = {{4{_zz_jumpTarget_1[27]}}, _zz_jumpTarget_1};
  assign _zz_jumpTarget_2 = {_zz_jumpTarget_3,_zz_jumpTarget_4};
  assign _zz_jumpTarget_3 = io_inst[9 : 0];
  assign _zz_jumpTarget_4 = io_inst[25 : 10];
  assign _zz_linkTarget_1 = {io_inst[25 : 10],2'b00};
  assign _zz_linkTarget = {{14{_zz_linkTarget_1[17]}}, _zz_linkTarget_1};
  assign nextPC = (io_pc + 32'h00000004);
  assign branchOffset = _zz_branchOffset;
  assign jumpTarget = (io_pc + _zz_jumpTarget);
  assign linkTarget = (io_rj + _zz_linkTarget);
  always @(*) begin
    if(io_isBranch) begin
      io_actualTarget = (io_pc + branchOffset);
    end else begin
      if(io_isJump) begin
        io_actualTarget = jumpTarget;
      end else begin
        io_actualTarget = linkTarget;
      end
    end
  end

  assign when_BRU_l56 = ((io_isBranch || io_isJR) || io_isJump);
  always @(*) begin
    if(when_BRU_l56) begin
      io_mispredict = ((io_predictJump ^ ((io_condition || io_isJR) || io_isJump)) || (((io_condition || io_isJR) || io_isJump) && (io_actualTarget != io_predictAddr)));
    end else begin
      io_mispredict = io_predictJump;
    end
  end


endmodule

//ALU_2 replaced by ALU

//ALU_1 replaced by ALU

module ALU (
  input      [31:0]   io_src1,
  input      [31:0]   io_src2,
  input      [4:0]    io_sa,
  input      [4:0]    io_op,
  output reg [31:0]   io_result
);
  localparam ALUOpType_ADD = 5'd0;
  localparam ALUOpType_ADDU = 5'd1;
  localparam ALUOpType_SUB = 5'd2;
  localparam ALUOpType_SUBU = 5'd3;
  localparam ALUOpType_AND_1 = 5'd4;
  localparam ALUOpType_OR_1 = 5'd5;
  localparam ALUOpType_XOR_1 = 5'd6;
  localparam ALUOpType_NOR_1 = 5'd7;
  localparam ALUOpType_SLT = 5'd8;
  localparam ALUOpType_SLTU = 5'd9;
  localparam ALUOpType_SLL_1 = 5'd10;
  localparam ALUOpType_SRL_1 = 5'd11;
  localparam ALUOpType_SRA_1 = 5'd12;
  localparam ALUOpType_LU12I = 5'd13;
  localparam ALUOpType_PCADDI = 5'd14;
  localparam ALUOpType_PCADDU12I = 5'd15;
  localparam ALUOpType_CPUCFG = 5'd16;
  localparam ALUOpType_IOCSR = 5'd17;

  wire       [0:0]    _zz_io_result;
  wire       [31:0]   _zz_io_result_1;
  wire       [31:0]   _zz_io_result_2;
  wire       [0:0]    _zz_io_result_3;
  wire       [31:0]   _zz_io_result_4;
  wire       [31:0]   _zz_io_result_5;
  `ifndef SYNTHESIS
  reg [71:0] io_op_string;
  `endif


  assign _zz_io_result = ($signed(_zz_io_result_1) < $signed(_zz_io_result_2));
  assign _zz_io_result_1 = io_src1;
  assign _zz_io_result_2 = io_src2;
  assign _zz_io_result_3 = (io_src1 < io_src2);
  assign _zz_io_result_4 = ($signed(_zz_io_result_5) >>> io_sa);
  assign _zz_io_result_5 = io_src1;
  `ifndef SYNTHESIS
  always @(*) begin
    case(io_op)
      ALUOpType_ADD : io_op_string = "ADD      ";
      ALUOpType_ADDU : io_op_string = "ADDU     ";
      ALUOpType_SUB : io_op_string = "SUB      ";
      ALUOpType_SUBU : io_op_string = "SUBU     ";
      ALUOpType_AND_1 : io_op_string = "AND_1    ";
      ALUOpType_OR_1 : io_op_string = "OR_1     ";
      ALUOpType_XOR_1 : io_op_string = "XOR_1    ";
      ALUOpType_NOR_1 : io_op_string = "NOR_1    ";
      ALUOpType_SLT : io_op_string = "SLT      ";
      ALUOpType_SLTU : io_op_string = "SLTU     ";
      ALUOpType_SLL_1 : io_op_string = "SLL_1    ";
      ALUOpType_SRL_1 : io_op_string = "SRL_1    ";
      ALUOpType_SRA_1 : io_op_string = "SRA_1    ";
      ALUOpType_LU12I : io_op_string = "LU12I    ";
      ALUOpType_PCADDI : io_op_string = "PCADDI   ";
      ALUOpType_PCADDU12I : io_op_string = "PCADDU12I";
      ALUOpType_CPUCFG : io_op_string = "CPUCFG   ";
      ALUOpType_IOCSR : io_op_string = "IOCSR    ";
      default : io_op_string = "?????????";
    endcase
  end
  `endif

  always @(*) begin
    case(io_op)
      ALUOpType_ADD, ALUOpType_LU12I, ALUOpType_PCADDI, ALUOpType_PCADDU12I : begin
        io_result = (io_src1 + io_src2);
      end
      ALUOpType_ADDU : begin
        io_result = (io_src1 + io_src2);
      end
      ALUOpType_SUB : begin
        io_result = (io_src1 - io_src2);
      end
      ALUOpType_SUBU : begin
        io_result = (io_src1 - io_src2);
      end
      ALUOpType_AND_1 : begin
        io_result = (io_src1 & io_src2);
      end
      ALUOpType_OR_1 : begin
        io_result = (io_src1 | io_src2);
      end
      ALUOpType_XOR_1 : begin
        io_result = (io_src1 ^ io_src2);
      end
      ALUOpType_NOR_1 : begin
        io_result = (~ (io_src1 | io_src2));
      end
      ALUOpType_SLT : begin
        io_result = {31'd0, _zz_io_result};
      end
      ALUOpType_SLTU : begin
        io_result = {31'd0, _zz_io_result_3};
      end
      ALUOpType_SLL_1 : begin
        io_result = (io_src1 <<< io_sa);
      end
      ALUOpType_SRL_1 : begin
        io_result = (io_src1 >>> io_sa);
      end
      ALUOpType_SRA_1 : begin
        io_result = _zz_io_result_4;
      end
      ALUOpType_CPUCFG : begin
        io_result = 32'h0;
        case(io_src1)
          32'h0 : begin
            io_result = 32'h00144200;
          end
          32'h00000001 : begin
            io_result = 32'h0001f1fc;
          end
          32'h00000002 : begin
            io_result = 32'h00004000;
          end
          32'h00000004 : begin
            io_result = 32'h06422c40;
          end
          32'h00000005 : begin
            io_result = 32'h00010001;
          end
          default : begin
          end
        endcase
      end
      default : begin
        io_result = 32'h0;
      end
    endcase
  end


endmodule

